import manifestJson from "./manifest.json" with { type: "json" };

/**
 * Paid plans L2 (spec 2026-09-29 §2.3.2) — WHICH VERSION OF WHICH DOCUMENT IS CURRENT.
 *
 * `manifest.json` is GENERATED by `pnpm generate:legal` (apps/ui/scripts/generate-legal-data.mjs):
 *   - TERMS and PRIVACY, from the drafts under apps/ui/legal/<locale>/: the draft's `Version N.M`
 *     and the sha256 of its exact Markdown bytes;
 *   - CONSENT_RENEWAL and CONSENT_IMMEDIATE_START (R-27), from the two checkout consent sentences
 *     `billing.consent.renewal` / `billing.consent.immediateStart` in apps/ui/messages/<locale>/
 *     billing.json: the sha256 of the sentence and the version `sha256-<its first 12 hex>`, so any
 *     edit of a sentence is a new version. A locale whose billing.json does not carry the two
 *     sentences yet has no consent entry, and `currentDocument` answers null for it (the checkout
 *     then refuses LEGAL_DOCUMENT_STALE — harmless while billing is off; P18 writes the sentences
 *     and regenerates);
 *   - the ARCHIVE (ruling Q-3): every TERMS and PRIVACY text that was ever current, kept byte for
 *     byte at apps/ui/legal/archive/<locale>/<sha256>.md, indexed here by kind, locale and hash with
 *     its version and path. The generator carries the committed index forward, so a text stays
 *     listed after its draft moves on; M1 attaches the version a person ACCEPTED by looking up the
 *     acceptance row's locale and sha256 (`archivedDocument`).
 * `tests/unit/legal-manifest.test.ts` pins that the committed file equals the generator's output,
 * so edit the draft or the catalogue and regenerate.
 */
export const LEGAL_DOCUMENT_KINDS = Object.freeze([
  "TERMS", "PRIVACY", "CONSENT_RENEWAL", "CONSENT_IMMEDIATE_START"
] as const);
export type LegalDocumentKind = typeof LEGAL_DOCUMENT_KINDS[number];
export type LegalDocumentPair = Readonly<{ version: string; sha256: string }>;
/** Only the two documents are archived; a consent sentence's text lives in its catalogue. */
export type LegalArchiveKind = Extract<LegalDocumentKind, "TERMS" | "PRIVACY">;
/** `path` is relative to dialectical-engine/: `apps/ui/legal/archive/<locale>/<sha256>.md`. */
export type LegalArchiveEntry = Readonly<{ version: string; sha256: string; path: string }>;

export type LegalManifestIndex = Readonly<{
  reacceptance: Readonly<Record<LegalDocumentKind, string | null>>;
  documents: Readonly<Record<LegalDocumentKind, ReadonlyMap<string, LegalDocumentPair>>>;
  /** kind -> locale -> sha256 -> entry. */
  archive: Readonly<Record<LegalArchiveKind, ReadonlyMap<string, ReadonlyMap<string, LegalArchiveEntry>>>>;
}>;

const MANIFEST_FORMAT = "debateai.legal-manifest.v1";
const ARCHIVE_KINDS: readonly LegalArchiveKind[] = Object.freeze(["TERMS", "PRIVACY"]);
const DOCUMENT_VERSION = /^([0-9]{1,4})\.([0-9]{1,4})$/u;
const CONSENT_VERSION = /^sha256-[0-9a-f]{12}$/u;
const SHA256 = /^[0-9a-f]{64}$/u;
const LOCALE = /^[a-z]{2}$/u;

/** The one spelling of an archive path; the generator's `legalArchivePath` writes the same. */
function archivePath(locale: string, sha256: string): string {
  return `apps/ui/legal/archive/${locale}/${sha256}.md`;
}

function isArchiveKind(kind: string): kind is LegalArchiveKind {
  return (ARCHIVE_KINDS as readonly string[]).includes(kind);
}

function invalid(): never {
  throw new TypeError("LEGAL_MANIFEST_INVALID");
}

function record(value: unknown): Readonly<Record<string, unknown>> {
  return value !== null && typeof value === "object" && !Array.isArray(value)
    ? value as Readonly<Record<string, unknown>> : invalid();
}

function isConsentKind(kind: LegalDocumentKind): boolean {
  return kind === "CONSENT_RENEWAL" || kind === "CONSENT_IMMEDIATE_START";
}

function isKind(value: string): value is LegalDocumentKind {
  return (LEGAL_DOCUMENT_KINDS as readonly string[]).includes(value);
}

/** A document is `N.M`; a consent sentence is `sha256-` + the first 12 hex of its own hash. */
function validPair(kind: LegalDocumentKind, pair: Readonly<Record<string, unknown>>): pair is LegalDocumentPair {
  if (typeof pair.version !== "string" || typeof pair.sha256 !== "string" || !SHA256.test(pair.sha256)) return false;
  return isConsentKind(kind)
    ? CONSENT_VERSION.test(pair.version) && pair.version === `sha256-${pair.sha256.slice(0, 12)}`
    : DOCUMENT_VERSION.test(pair.version);
}

/** The archive member: known kinds only, each entry at its own path with an `N.M` version. */
function parseArchive(value: unknown): LegalManifestIndex["archive"] {
  const root = record(value);
  for (const key of Object.keys(root)) {
    if (!isArchiveKind(key)) invalid();
  }
  const byKind = {} as Record<LegalArchiveKind, ReadonlyMap<string, ReadonlyMap<string, LegalArchiveEntry>>>;
  for (const kind of ARCHIVE_KINDS) {
    const locales = new Map<string, ReadonlyMap<string, LegalArchiveEntry>>();
    if (Object.hasOwn(root, kind)) {
      for (const [locale, entries] of Object.entries(record(root[kind]))) {
        if (!LOCALE.test(locale)) invalid();
        const byHash = new Map<string, LegalArchiveEntry>();
        for (const [sha256, raw] of Object.entries(record(entries))) {
          const entry = record(raw);
          if (!SHA256.test(sha256) || typeof entry.version !== "string" || !DOCUMENT_VERSION.test(entry.version)
            || entry.path !== archivePath(locale, sha256)) invalid();
          byHash.set(sha256, Object.freeze({ version: entry.version, sha256, path: archivePath(locale, sha256) }));
        }
        locales.set(locale, byHash);
      }
    }
    byKind[kind] = locales;
  }
  return Object.freeze(byKind);
}

/**
 * The manifest's own grammar, refused whole (LEGAL_MANIFEST_INVALID) rather than half-read: an
 * unknown kind, a bad locale, a pair of the wrong shape for its kind, a re-acceptance floor on
 * a consent sentence (a changed sentence is simply a new version, asked for at the next checkout),
 * an archive entry off its path, or a current TERMS/PRIVACY pair the archive does not hold (Q-3:
 * whatever a person accepts today must be attachable later).
 */
export function parseLegalManifest(value: unknown): LegalManifestIndex {
  const root = record(value);
  if (root.format !== MANIFEST_FORMAT) invalid();
  const reacceptance = record(root.reacceptance);
  const documents = record(root.documents);
  for (const key of [...Object.keys(reacceptance), ...Object.keys(documents)]) {
    if (!isKind(key)) invalid();
  }
  const archive = parseArchive(root.archive);
  const floors = {} as Record<LegalDocumentKind, string | null>;
  const byKind = {} as Record<LegalDocumentKind, ReadonlyMap<string, LegalDocumentPair>>;
  for (const kind of LEGAL_DOCUMENT_KINDS) {
    const floor = reacceptance[kind] ?? null;
    if (floor !== null && (isConsentKind(kind) || typeof floor !== "string" || !DOCUMENT_VERSION.test(floor))) invalid();
    floors[kind] = floor as string | null;
    const locales = new Map<string, LegalDocumentPair>();
    if (Object.hasOwn(documents, kind)) {
      for (const [locale, entry] of Object.entries(record(documents[kind]))) {
        const pair = record(entry);
        if (!LOCALE.test(locale) || !validPair(kind, pair)) invalid();
        locales.set(locale, Object.freeze({ version: pair.version, sha256: pair.sha256 }));
      }
    }
    byKind[kind] = locales;
  }
  for (const kind of ARCHIVE_KINDS) {
    for (const [locale, pair] of byKind[kind]) {
      const archived = archive[kind].get(locale)?.get(pair.sha256);
      if (archived === undefined || archived.version !== pair.version) invalid();
    }
  }
  return Object.freeze({ reacceptance: Object.freeze(floors), documents: Object.freeze(byKind), archive });
}

const MANIFEST = parseLegalManifest(manifestJson);

export function currentDocument(kind: LegalDocumentKind, locale: string): LegalDocumentPair | null {
  return MANIFEST.documents[kind]?.get(locale) ?? null;
}

export function isCurrentDocument(
  kind: LegalDocumentKind,
  locale: string,
  pair: Readonly<{ version: unknown; sha256: unknown }>
): boolean {
  const current = currentDocument(kind, locale);
  return current !== null && pair.version === current.version && pair.sha256 === current.sha256;
}

/**
 * The version from which people who accepted an OLDER version must accept again, or null when no
 * re-acceptance is required. Set in the generator's DOCUMENTS config (`reacceptanceFrom`) when a
 * draft's change is material; the generator carries it into manifest.json. Always null for the two
 * consent kinds.
 */
export function reacceptanceFloor(kind: LegalDocumentKind): string | null {
  return MANIFEST.reacceptance[kind] ?? null;
}

function versionParts(version: string): readonly [number, number] {
  const match = DOCUMENT_VERSION.exec(version);
  if (match === null) throw new TypeError("LEGAL_DOCUMENT_VERSION_INVALID");
  return [Number(match[1]), Number(match[2])];
}

/** "2.10" >= "2.9": major then minor, as integers. TERMS and PRIVACY versions only. */
export function documentVersionAtLeast(version: string, floor: string): boolean {
  const [major, minor] = versionParts(version);
  const [floorMajor, floorMinor] = versionParts(floor);
  return major > floorMajor || (major === floorMajor && minor >= floorMinor);
}

export function legalManifestLocales(kind: LegalDocumentKind): readonly string[] {
  return Object.freeze([...(MANIFEST.documents[kind]?.keys() ?? [])].sort());
}

/**
 * Ruling Q-3: the archived text of one version — found by the locale and the sha256 an acceptance
 * row names — or null (a consent kind, a locale or a hash the archive never held). The file at
 * `path` holds exactly the bytes whose sha256 is `sha256`; a reader still compares the hash.
 */
export function archivedDocument(kind: LegalDocumentKind, locale: string, sha256: string): LegalArchiveEntry | null {
  if (!isArchiveKind(kind)) return null;
  return MANIFEST.archive[kind].get(locale)?.get(sha256) ?? null;
}

/**
 * Every archived version of one document in one locale, newest version first (ties by hash, so the
 * order is stable) — what a "previous versions" page lists. `index` defaults to the committed manifest.
 */
export function legalArchive(
  kind: LegalDocumentKind,
  locale: string,
  index: LegalManifestIndex = MANIFEST
): readonly LegalArchiveEntry[] {
  if (!isArchiveKind(kind)) return Object.freeze([]);
  const entries = [...(index.archive[kind].get(locale)?.values() ?? [])];
  entries.sort((left, right) => {
    const leftNewer = documentVersionAtLeast(left.version, right.version);
    const rightNewer = documentVersionAtLeast(right.version, left.version);
    if (leftNewer !== rightNewer) return leftNewer ? -1 : 1;
    return left.sha256 < right.sha256 ? -1 : left.sha256 > right.sha256 ? 1 : 0;
  });
  return Object.freeze(entries);
}
